mapper.select:
select spu_id,product_name,subtitle,main_image,price_min price,publish_status,
       case when del_flag='0' and publish_status='1' then 1 else 0 end available
from mall_spu where spu_id=#{spuId}

select  from mall_member_favorite f
left join mall_spu p on p.spu_id=f.spu_id where f.member_id=#{memberId}
order by f.create_time desc,f.favorite_id desc

select  from mall_member_browse_history h
left join mall_spu p on p.spu_id=h.spu_id where h.member_id=#{memberId}
order by h.last_view_time desc,h.history_id desc limit 200
